// ---------------------------------------------------------------------------
// Núcleo de la fase 08. Ensamblaje determinista: ni una llamada a LLM.
// Todo el juicio editorial ya lo hicieron 05 (qué dice cada fuente) y 07 (tema).
// Aquí solo se selecciona, clasifica, ordena y renderiza.
// ---------------------------------------------------------------------------

const CAT_LABEL = {
  internacional: 'Internacional', economia: 'Economía', tecnologia: 'Tecnología',
  ciencia: 'Ciencia', espana: 'España', cultura: 'Cultura',
  deportes: 'Deportes', sociedad: 'Sociedad'
};

// 05 marca como "discrepancia" cualquier diferencia entre fuentes, y en los datos
// reales eso es el 100% de los clusters: la mitad son matices de redacción y una
// cuarta parte son simples ausencias de cobertura. Si el briefing las destacara
// todas, el aviso dejaría de significar nada. Se separan aquí sin LLM.
const AUSENCIA = /no\s+(se\s+)?(menciona|especifica|indica|detalla|precisa|proporciona|aporta|ofrece|da)|sin\s+(datos|detalles?|especificar|concretar)|no\s+(hay|consta|figura|aparece)|no\s+lo\s+(menciona|especifica)/i;
const NUM = /\d[\d.,]*/g;

function normalizar(s) {
  return String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '')
    .replace(/\s+/g, ' ').trim().toLowerCase();
}

function cifras(s) {
  const m = String(s ?? '').match(NUM) || [];
  return new Set(m.map(n => n.replace(/\./g, '').replace(/,/g, '.').replace(/\.$/, '')));
}

function clasificarDiscrepancia(d) {
  const vals = Object.values((d && d.version_por_fuente) || {});
  if (vals.length < 2) return 'incompleta';
  if (vals.some(v => AUSENCIA.test(String(v)))) return 'cobertura';
  const conjuntos = vals.map(cifras);
  if (conjuntos.every(c => c.size > 0)) {
    const firmas = new Set(conjuntos.map(c => [...c].sort().join('|')));
    if (firmas.size > 1) return 'cifras';
  }
  if (new Set(vals.map(normalizar)).size === 1) return 'identica';
  return 'matiz';
}

const esc = s => String(s ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');

// Convierte la lista de hechos confirmados en una frase en prosa. El briefing
// no debe leerse como un volcado de bullets.
function enProsa(frases) {
  const f = frases.map(x => String(x).replace(/[.\s]+$/, '')).filter(Boolean);
  if (!f.length) return '';
  const t = f.length === 1 ? f[0] + '.' : f.slice(0, -1).join('; ') + ', y ' + f[f.length - 1] + '.';
  return t.charAt(0).toUpperCase() + t.slice(1);
}

function construirBriefing(filas, fecha) {
  const items = filas.map(r => {
    const a = r.analysis || {};
    const disc = (a.discrepancias || []).map(d => ({ tipo: clasificarDiscrepancia(d), d }));
    return {
      id: r.id,
      categoria: r.categoria,
      source_count: r.source_count,
      sources: r.sources || [],
      articles: r.articles || [],
      analysis: a,
      fuertes: disc.filter(x => x.tipo === 'cifras').map(x => x.d),
      descartadas: disc.filter(x => x.tipo !== 'cifras').length
    };
  });

  const porCat = {};
  for (const it of items) (porCat[it.categoria] ||= []).push(it);
  for (const c of Object.keys(porCat)) {
    porCat[c].sort((x, y) => (y.source_count - x.source_count) || (y.fuertes.length - x.fuertes.length) || (x.id - y.id));
  }
  // Categorías por volumen: el tema con más cobertura del día abre el briefing.
  const cats = Object.keys(porCat).sort((a, b) => porCat[b].length - porCat[a].length);

  const nDiv = items.reduce((s, x) => s + x.fuertes.length, 0);
  const nMedios = new Set(items.flatMap(x => x.sources)).size;
  const nDesc = items.reduce((s, x) => s + x.descartadas, 0);

  return { items, porCat, cats, nDiv, nMedios, nDesc, fecha };
}

const CSS = `
/* Índigo y bronce. Dos tonos con papeles distintos y complementarios:
   el índigo es la estructura —cabecera, temas, índice, enlaces— y el bronce
   aparece en un único sitio de todo el documento, donde las fuentes se
   contradicen en una cifra. Que el color más saturado señale siempre lo mismo
   es lo que hace que se lea "aquí hay contraste" y no "aquí hay opinión";
   por eso quedan descartados el rojo, el magenta y el naranja saturado, que
   son el código cromático de la alarma y del sensacionalismo.

   La tensión frío/cálido no es decoración: un documento de un solo tono se lee
   siempre más plano de lo que es, y una versión anterior en gris único resultó
   apagada precisamente por eso. El bronce funciona porque está muy desaturado
   y ocupa poquísima superficie — subirle la saturación lo convertiría en el
   naranja de alerta que el proyecto no quiere.

   Los blancos de tarjeta y los filetes son tintes de estos tonos, no colores
   nuevos. */
:root{
  --paper:#F0F1F5; --card:#FFFFFF; --ink:#171A26; --muted:#666C80;
  --rule:#D8DAE4; --deep:#232E63; --accent:#8A6218; --wash:#F2EAD9;
  /* Cada sistema con su fuente nombrada, en vez de confiar en el genérico: sin
     esto, Android caía en lo que hubiera. Con el bot multiusuario eso dejaría de
     ser un detalle, porque sería el aspecto por defecto de la mayoría.
     Android → Roboto; Apple → San Francisco; Windows → Segoe UI. */
  --sans:Roboto,system-ui,-apple-system,"Segoe UI","Helvetica Neue",Arial,sans-serif;
  --mono:ui-monospace,"Roboto Mono","SF Mono","DejaVu Sans Mono","Droid Sans Mono",Menlo,Consolas,monospace;
}
@media (prefers-color-scheme:dark){
  :root{--paper:#0E1017; --card:#151824; --ink:#DFE2ED; --muted:#8990A5;
        --rule:#242938; --deep:#8E9BD8; --accent:#C9963C; --wash:#241D0F;}
}
:root[data-theme="dark"]{--paper:#0E1017; --card:#151824; --ink:#DFE2ED; --muted:#8990A5;
  --rule:#242938; --deep:#8E9BD8; --accent:#C9963C; --wash:#241D0F;}
:root[data-theme="light"]{--paper:#F0F1F5; --card:#FFFFFF; --ink:#171A26; --muted:#666C80;
  --rule:#D8DAE4; --deep:#232E63; --accent:#8A6218; --wash:#F2EAD9;}
*{box-sizing:border-box}
body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--sans);
     font-size:16px;line-height:1.6;-webkit-font-smoothing:antialiased}
.wrap{max-width:1080px;margin:0 auto;padding:0 24px 90px}

/* La fecha ES el titular, sobre una banda del tono profundo. El color necesita
   superficie: en una versión anterior aparecía solo en dos bordes de 2 px y el
   documento entero se leía gris. */
header.top{background:var(--deep);color:#fff;margin:0 -24px;
           padding:56px 24px 30px;border-radius:0 0 4px 4px}
.mark{font-family:var(--mono);font-size:10.5px;letter-spacing:.2em;text-transform:uppercase;
      color:#fff;opacity:.62;margin:0 0 22px}
header.top h1{font-size:clamp(1.95rem,5vw,3.05rem);line-height:1.02;margin:0 0 26px;
              font-weight:700;letter-spacing:-.034em;text-wrap:balance;color:#fff}
.stats{display:flex;flex-wrap:wrap;gap:0 40px;margin:0}
.stats div{display:flex;flex-direction:column-reverse}
.stats dt{font-family:var(--mono);font-size:9px;letter-spacing:.13em;text-transform:uppercase;
          color:#fff;opacity:.58;margin:3px 0 0}
.stats dd{margin:0;font-family:var(--mono);font-size:25px;font-weight:600;
          font-variant-numeric:tabular-nums;line-height:1;color:#fff}
.stats .hot dd{text-decoration:underline;text-decoration-thickness:2px;
               text-underline-offset:5px}

.cols{display:grid;grid-template-columns:1fr;gap:34px;margin-top:36px}
@media(min-width:900px){.cols{grid-template-columns:178px 1fr;gap:56px}
  nav.idx{position:sticky;top:24px;align-self:start;max-height:calc(100vh - 48px);overflow-y:auto}}
nav.idx h2{font-family:var(--mono);font-size:10px;letter-spacing:.16em;text-transform:uppercase;
           color:var(--muted);margin:0 0 12px;font-weight:600}
nav.idx ol{list-style:none;margin:0;padding:0}
nav.idx a{display:flex;justify-content:space-between;align-items:baseline;gap:10px;
          text-decoration:none;color:var(--ink);padding:7px 0;
          border-bottom:1px solid var(--rule);font-size:13.5px}
nav.idx a:hover,nav.idx a:focus-visible{color:var(--deep)}
nav.idx .n{font-family:var(--mono);font-size:11.5px;color:var(--muted);
           font-variant-numeric:tabular-nums;display:inline-flex;align-items:center;gap:6px}
nav.idx .d{width:5px;height:5px;border-radius:50%;background:var(--accent);display:block}

section.cat{scroll-margin-top:20px}
section.cat > h2{font-size:11px;font-weight:700;letter-spacing:.17em;text-transform:uppercase;
   color:var(--deep);margin:46px 0 0;padding-bottom:10px;border-bottom:2px solid var(--deep)}
article.story{padding:26px 0;border-bottom:1px solid var(--rule)}
.meta{font-family:var(--mono);font-size:9.5px;letter-spacing:.13em;text-transform:uppercase;
      color:var(--muted);margin:0 0 8px}
.story h3{font-size:1.3rem;line-height:1.25;margin:0 0 9px;font-weight:700;
          letter-spacing:-.021em;text-wrap:balance}
.why{margin:0 0 15px;color:var(--muted);font-size:15.5px;max-width:66ch}
.outlets{display:flex;flex-wrap:wrap;gap:6px;margin:0 0 16px}
.outlets a{font-family:var(--mono);font-size:11px;padding:4px 9px;border:1px solid var(--rule);
           border-radius:2px;color:var(--muted);background:var(--card);text-decoration:none;
           display:inline-flex;align-items:center;gap:5px;transition:border-color .12s,color .12s}
.outlets a:hover,.outlets a:focus-visible{color:var(--deep);border-color:var(--deep)}
.outlets a::after{content:"\\2197";font-size:9.5px;opacity:.6}

/* El único uso del bronce en todo el documento, y con superficie: relleno, no
   un filete. Es el elemento diferencial del briefing y tiene que verse como tal. */
.diverge{margin:0 0 18px;padding:13px 16px;background:var(--wash);
         border-left:3px solid var(--accent);border-radius:0 3px 3px 0}
.diverge .dh{font-family:var(--mono);font-size:10px;letter-spacing:.14em;text-transform:uppercase;
             color:var(--accent);font-weight:600;margin:0 0 6px}
.diverge .aspect{font-size:15px;font-weight:600;margin:0 0 11px}
.diverge ul{list-style:none;margin:0;padding:0;display:grid;gap:5px}
.diverge li{display:grid;grid-template-columns:118px 1fr;gap:14px;align-items:baseline}
@media(max-width:520px){.diverge li{grid-template-columns:1fr;gap:1px}}
.diverge .src{font-family:var(--mono);font-size:11px;color:var(--muted);letter-spacing:.04em}
.diverge .val{font-size:15px;font-weight:600;font-variant-numeric:tabular-nums;color:var(--ink)}
.diverge + .diverge{margin-top:-6px}

details.more{border-top:1px dashed var(--rule);padding-top:13px}
details.more summary{font-family:var(--mono);font-size:10.5px;letter-spacing:.11em;
   text-transform:uppercase;color:var(--muted);cursor:pointer;list-style:none;
   display:inline-flex;align-items:center;gap:7px}
details.more summary::-webkit-details-marker{display:none}
details.more summary::before{content:"+";font-size:13px;line-height:1;font-weight:700}
details.more[open] summary::before{content:"\\2212"}
details.more summary:hover,details.more summary:focus-visible{color:var(--deep)}
.mblock{margin:14px 0 0}
.mblock p{margin:0 0 12px;font-size:16px;line-height:1.68;max-width:66ch}
.mblock p:last-child{margin-bottom:0}
.tail{margin:14px 0 0;font-family:var(--mono);font-size:10.5px;color:var(--muted)}

footer{margin-top:64px;padding-top:24px;border-top:2px solid var(--deep);
       font-family:var(--mono);font-size:11px;color:var(--muted);line-height:1.85}
a:focus-visible,summary:focus-visible{outline:2px solid var(--deep);outline-offset:3px}
@media(prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important}}
`;

const MESES = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
function fechaLarga(iso) {
  const [y, m, d] = String(iso).split('-').map(Number);
  return `${d} de ${MESES[m - 1]} de ${y}`;
}

const DIAS = ['domingo','lunes','martes','miércoles','jueves','viernes','sábado'];
function diaSemana(iso) {
  const [y, m, d] = String(iso).split('-').map(Number);
  const n = new Date(Date.UTC(y, m - 1, d)).getUTCDay();
  return DIAS[n].charAt(0).toUpperCase() + DIAS[n].slice(1);
}

function renderHTML(b) {
  const o = [];
  o.push(`<!doctype html><html lang="es"><head><meta charset="utf-8">`);
  o.push(`<meta name="viewport" content="width=device-width,initial-scale=1">`);
  o.push(`<title>Briefing · ${fechaLarga(b.fecha)}</title><style>${CSS}</style></head><body>`);
  o.push('<div class="wrap">');

  // La fecha ES el titular. Es lo único que cambia de verdad cada día, así que
  // es lo único que merece el sitio de máxima jerarquía; una tesis fija en ese
  // hueco se gasta al leerla treinta mañanas seguidas.
  o.push('<header class="top">');
  o.push('<p class="mark">news-briefing-ai</p>');
  o.push(`<h1>${esc(diaSemana(b.fecha))},<br>${esc(fechaLarga(b.fecha))}</h1>`);
  o.push('<dl class="stats">'
    + `<div><dt>Acontecimientos</dt><dd>${b.items.length}</dd></div>`
    + `<div><dt>Medios contrastados</dt><dd>${b.nMedios}</dd></div>`
    + `<div class="hot"><dt>Cifras en conflicto</dt><dd>${b.nDiv}</dd></div>`
    + `<div><dt>Diferencias descartadas</dt><dd>${b.nDesc}</dd></div>`
    + '</dl>');
  o.push('</header>');

  o.push('<div class="cols"><nav class="idx"><h2>Índice</h2><ol>');
  for (const c of b.cats) {
    const nd = b.porCat[c].reduce((s, x) => s + x.fuertes.length, 0);
    const dot = nd ? '<span class="d"></span>' : '';
    o.push(`<li><a href="#c-${c}"><span>${esc(CAT_LABEL[c] || c)}</span>`
      + `<span class="n">${dot}${b.porCat[c].length}</span></a></li>`);
  }
  o.push('</ol></nav><main>');

  for (const c of b.cats) {
    o.push(`<section class="cat" id="c-${c}"><h2>${esc(CAT_LABEL[c] || c)}</h2>`);
    for (const it of b.porCat[c]) {
      const a = it.analysis;
      o.push('<article class="story">');
      o.push(`<p class="meta">${it.source_count} ${it.source_count > 1 ? 'medios' : 'medio'}</p>`);
      o.push(`<h3>${esc(a.que_paso)}</h3>`);
      if (a.por_que_importa) o.push(`<p class="why">${esc(a.por_que_importa)}</p>`);

      // La caja de cada medio ES el enlace a su artículo. Un artículo por medio,
      // en el orden en que las fuentes entraron al cluster.
      const porMedio = new Map();
      for (const art of it.articles) if (!porMedio.has(art.source_name)) porMedio.set(art.source_name, art.link);
      o.push('<div class="outlets">' + [...porMedio].map(([medio, link]) =>
        `<a href="${esc(link)}" target="_blank" rel="noopener">${esc(medio)}</a>`).join('') + '</div>');

      for (const d of it.fuertes) {
        o.push('<div class="diverge"><p class="dh">Las cifras no coinciden</p>');
        o.push(`<p class="aspect">${esc(d.aspecto)}</p><ul>`);
        for (const [k, v] of Object.entries(d.version_por_fuente || {})) {
          o.push(`<li><span class="src">${esc(k)}</span><span class="val">${esc(v)}</span></li>`);
        }
        o.push('</ul></div>');
      }

      // "Ver más" solo existe si 05 escribió un desarrollo con sustancia. Cuando
      // las fuentes son teasers de RSS escuetos, 05 devuelve una línea o nada —
      // correctamente, porque forzarle una extensión mínima le hacía inventar.
      const desarrollo = Array.isArray(a.desarrollo) ? a.desarrollo.join('\n\n') : (a.desarrollo || '');
      const parrafos = desarrollo.split(/\n\s*\n/).map(p => p.trim()).filter(Boolean);
      const palabras = desarrollo.split(/\s+/).filter(Boolean).length;
      if (parrafos.length && palabras >= 25) {
        o.push('<details class="more"><summary>Ver más</summary><div class="mblock">');
        for (const p of parrafos) o.push(`<p>${esc(p)}</p>`);
        o.push('</div><p class="tail">Para ir más allá, las fuentes originales están arriba.</p></details>');
      }
      o.push('</article>');
    }
    o.push('</section>');
  }
  o.push('</main></div>');
  o.push(`<footer>Generado por news-briefing-ai a partir de ${b.items.length} acontecimientos cubiertos por 2 o más medios.<br>`
    + `De las ${b.nDiv + b.nDesc} diferencias que detectó el análisis, solo ${b.nDiv} son contradicciones numéricas reales; `
    + `el resto son matices de redacción o coberturas desiguales y no se muestran.<br>`
    + `Los medios se listan en el orden en que cubrieron cada hecho. El sistema no los clasifica ni los valora.<br>`
    + `El sistema no sustituye al periodismo: cada pieza enlaza a sus fuentes originales.</footer>`);
  o.push('</div></body></html>');
  return o.join('\n');
}

// --- Entrada/salida del nodo -------------------------------------------------
const filas = $input.all().map(i => i.json);

// Fecha del briefing en día natural UTC, el mismo corte que usa la consulta de
// selección y que el tope diario de 05. Un corte distinto aquí desalinearía el
// nombre del briefing respecto a su contenido.
const fecha = new Date().toISOString().slice(0, 10);

const b = construirBriefing(filas, fecha);
const html = renderHTML(b);

// El payload guarda la selección ya clasificada, no el HTML: es lo que permite
// re-renderizar a otro formato sin volver a analizar nada.
const payload = {
  fecha: b.fecha,
  orden_categorias: b.cats,
  medios: b.nMedios,
  discrepancias_descartadas: b.nDesc,
  items: b.items.map(it => ({
    id: it.id, categoria: it.categoria, source_count: it.source_count,
    sources: it.sources, articles: it.articles, analysis: it.analysis,
    divergencias_numericas: it.fuertes
  }))
};

return [{
  json: {
    briefing_date: b.fecha,
    cluster_count: b.items.length,
    divergence_count: b.nDiv,
    payload: JSON.stringify(payload),
    content_html: html
  }
}];
